let authMode="login",user=null,servers=[],dms=[],activeServer=null,activeChannel=null,activeDm=null,activeMembers=[],modViewEnabled=false,lastMessageId=0,status="online",pollTimer=null,presenceLoop=null,serverLoop=null,socket=null,voiceRoom=null,localStream=null,screenStream=null,peerConnections=new Map(),remoteStreams=new Map(),incomingDmId=null,muted=false,typingTimer=null,typingActive=false,typingUsers=new Map(),iceServers=[{urls:"stun:stun.l.google.com:19302"}];
function msg(el,text,good=false){el.textContent=text||"";el.style.color=good?"var(--success)":""}
let selectedAttachments=[];
function formatFileSize(bytes){if(bytes<1024)return bytes+" B";if(bytes<1024*1024)return (bytes/1024).toFixed(1)+" KB";return (bytes/1024/1024).toFixed(1)+" MB"}
function renderAttachmentPreview(){const box=$("attachment-preview");box.replaceChildren();box.classList.toggle("hidden",!selectedAttachments.length);selectedAttachments.forEach((file,index)=>{const chip=document.createElement("div");chip.className="attachment-chip";const label=document.createElement("span");label.textContent=file.name+" · "+formatFileSize(file.size);const remove=document.createElement("button");remove.type="button";remove.textContent="×";remove.title="Remove "+file.name;remove.onclick=()=>{selectedAttachments.splice(index,1);renderAttachmentPreview()};chip.append(label,remove);box.append(chip)})}
function fileAsBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(",")[1]||"");reader.onerror=()=>reject(new Error("Could not read "+file.name));reader.readAsDataURL(file)})}
$("attach-button").onclick=()=>{if(activeChannel||activeDm)$("attachment-input").click()};
$("attachment-input").onchange=()=>{const incoming=[...$("attachment-input").files];$("attachment-input").value="";for(const file of incoming){if(selectedAttachments.length>=4){showToast("You can attach up to 4 files per message.");break}if(file.size>8*1024*1024){showToast(file.name+" is larger than 8 MB.");continue}if(selectedAttachments.reduce((sum,f)=>sum+f.size,0)+file.size>16*1024*1024){showToast("Attachments together must be 16 MB or smaller.");break}selectedAttachments.push(file)}renderAttachmentPreview()};

function showToast(message,kind="error"){const toast=document.createElement("div");toast.className="app-toast"+(kind==="success"?" app-toast-success":"");toast.textContent=message;document.body.append(toast);requestAnimationFrame(()=>toast.classList.add("visible"));setTimeout(()=>{toast.classList.remove("visible");setTimeout(()=>toast.remove(),180)},3200)}
function showInputDialog({title,description="",placeholder="",value="",submitLabel="Continue"}){return new Promise(resolve=>{const dialog=$("action-dialog"),form=$("action-dialog-form"),input=$("action-dialog-input");$("action-dialog-title").textContent=title;$("action-dialog-description").textContent=description;$("action-dialog-submit").textContent=submitLabel;input.placeholder=placeholder;input.value=value;$("action-dialog-error").textContent="";dialog.showModal();input.focus();const finish=result=>{dialog.close();form.removeEventListener("submit",submit);$("action-dialog-cancel").removeEventListener("click",cancel);dialog.removeEventListener("cancel",onCancel);resolve(result)};const submit=e=>{e.preventDefault();const result=input.value.trim();if(!result){$("action-dialog-error").textContent="Please enter a value.";input.focus();return}finish(result)};const cancel=()=>finish(null);const onCancel=()=>finish(null);form.addEventListener("submit",submit);$("action-dialog-cancel").addEventListener("click",cancel);dialog.addEventListener("cancel",onCancel,{once:true})})}
async function api(url,opt={}){const r=await fetch(url,{credentials:"include",cache:"no-store",headers:{"Content-Type":"application/json",...(opt.headers||{})},...opt});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||"Something went wrong.");return d}
function setMode(mode){authMode=mode;const reg=mode==="register";$("login-tab").classList.toggle("active",!reg);$("register-tab").classList.toggle("active",reg);$("display-name-wrap").classList.toggle("hidden",!reg);$("password").autocomplete=reg?"new-password":"current-password";$("password-hint").textContent=reg?"Use at least 12 characters.":"Use the password you chose when creating your account.";$("auth-submit").textContent=reg?"Create account":"Sign in";msg($("auth-message"),"")}
function setAvatar(el,url,fallback){el.replaceChildren();if(url){const img=document.createElement("img");img.src=url;img.alt="";img.className="avatar-image";el.append(img)}else el.textContent=(fallback||"?")[0].toUpperCase()}
function showApp(u){user=u;$("site-announcements-tab").classList.toggle("hidden",!canPostSiteAnnouncements());ensureVoiceSocket();if(!presenceLoop){presenceLoop=setInterval(heartbeat,25000);serverLoop=setInterval(()=>{loadServers();loadDms()},20000)}$("auth-view").classList.add("hidden");$("app-view").classList.remove("hidden");const n=u.displayName||u.username;$("profile-name").replaceChildren();appendName($("profile-name"),n,u.siteRole,null);$("profile-handle").textContent="@"+u.username;setAvatar($("profile-avatar"),u.avatarData,n);setAvatar($("rail-avatar"),u.avatarData,n);$("edit-display-name").value=n;setAvatar($("pfp-preview"),u.avatarData,n);heartbeat();loadServers();loadDms();joinServerFromLink()}
function showAuth(){leaveVoiceCall();if(socket){socket.disconnect();socket=null}$("app-view").classList.add("hidden");$("auth-view").classList.remove("hidden");if(pollTimer)clearInterval(pollTimer);if(presenceLoop)clearInterval(presenceLoop);if(serverLoop)clearInterval(serverLoop);pollTimer=presenceLoop=serverLoop=null;user=null}

function ensureVoiceSocket(){if(socket||typeof io!=="function")return;socket=io({withCredentials:true});socket.on("connect",()=>{$("connection-label").innerHTML='<span class="online-dot"></span><span>Connected</span>';if(activeDm)watchTyping("dm",activeDm);else if(activeChannel)watchTyping("channel",activeChannel)});socket.on("disconnect",()=>{$("connection-label").textContent="Reconnecting…";if(voiceRoom)leaveVoiceCall(false)});socket.on("disconnect",()=>{typingUsers.clear();renderTyping()});socket.on("site:announcement",p=>queueSiteAnnouncement(p));socket.on("typing:update",p=>{if(!isCurrentTypingChat(p))return;if(p.isTyping)typingUsers.set(String(p.userId),p.displayName||p.username);else typingUsers.delete(String(p.userId));renderTyping()});socket.on("message:deleted",p=>{if((p.type===(activeDm?"dm":"channel"))&&String(p.chatId)===String(activeDm||activeChannel))markMessageDeleted(p.messageId)});socket.on("server:deleted",p=>{servers=servers.filter(s=>String(s.id)!==String(p.serverId));if(activeServer&&String(activeServer.id)===String(p.serverId))home();renderServers()});socket.on("voice:peer-joined",p=>{if(voiceRoom)makePeer(p.peerId,false)});socket.on("voice:peer-left",p=>removePeer(p.peerId));socket.on("voice:declined",p=>{if(voiceRoom?.type==="dm"&&String(voiceRoom.id)===String(p.dmId))$("call-subtitle").textContent="Your friend declined the call."});socket.on("voice:signal",async p=>{try{let pc=peerConnections.get(p.from);if(!pc)pc=makePeer(p.from,false);if(p.signal.description){await pc.setRemoteDescription(p.signal.description);if(p.signal.description.type==="offer"){const answer=await pc.createAnswer();await pc.setLocalDescription(answer);socket.emit("voice:signal",{target:p.from,signal:{description:pc.localDescription}})}}else if(p.signal.candidate)await pc.addIceCandidate(p.signal.candidate)}catch(e){console.error("Voice signal error:",e)}});socket.on("voice:incoming",p=>{if(voiceRoom||$("incoming-call-dialog").open)return;incomingDmId=p.dmId;$("incoming-call-text").textContent=(p.callerName||"Your friend")+" is inviting you to a voice call.";$("incoming-call-dialog").showModal()})}
function addCallParticipant(id,label,avatarData,isLocal=false){if(document.getElementById("call-participant-"+id))return;const tile=document.createElement("div");tile.id="call-participant-"+id;tile.className="call-participant"+(isLocal?" call-participant-local":"");const avatar=document.createElement("div");avatar.className="call-participant-avatar";if(avatarData)setAvatar(avatar,avatarData,label);else avatar.textContent=(label||"?").trim().charAt(0).toUpperCase()||"?";const name=document.createElement("strong");name.textContent=label||"Participant";const status=document.createElement("span");status.className="call-participant-status";status.textContent=isLocal?(muted?"Muted":"You"):"Voice connected";tile.append(avatar,name,status);$("call-stage").append(tile)}
function makePeer(peerId,initiator){if(peerConnections.has(peerId))return peerConnections.get(peerId);addCallParticipant("peer-"+peerId,"Participant",null,false);const pc=new RTCPeerConnection({iceServers});localStream?.getAudioTracks().forEach(t=>pc.addTrack(t,localStream));const videoSender=pc.addTransceiver("video",{direction:"sendrecv"}).sender;if(screenStream)videoSender.replaceTrack(screenStream.getVideoTracks()[0]);pc.onicecandidate=e=>{if(e.candidate)socket.emit("voice:signal",{target:peerId,signal:{candidate:e.candidate}})};pc.ontrack=e=>{if(e.track.kind==="audio"){let audio=document.getElementById("remote-audio-"+peerId);if(!audio){audio=document.createElement("audio");audio.id="remote-audio-"+peerId;audio.autoplay=true;audio.hidden=true;$("call-stage").append(audio)}audio.srcObject=e.streams[0]||new MediaStream([e.track]);return}let media=document.getElementById("remote-"+peerId);if(!media){media=document.createElement("video");media.id="remote-"+peerId;media.autoplay=true;media.playsInline=true;media.className="remote-screen";media.setAttribute("aria-label","Remote screen share");$("call-stage").append(media)}media.srcObject=e.streams[0]||new MediaStream([e.track])};pc.onconnectionstatechange=()=>{if(pc.connectionState==="failed"||pc.connectionState==="closed")removePeer(peerId)};peerConnections.set(peerId,pc);if(initiator)pc.createOffer().then(o=>pc.setLocalDescription(o)).then(()=>socket.emit("voice:signal",{target:peerId,signal:{description:pc.localDescription}})).catch(console.error);return pc}
function removePeer(peerId){const pc=peerConnections.get(peerId);if(pc)pc.close();peerConnections.delete(peerId);remoteStreams.delete(peerId);document.getElementById("remote-"+peerId)?.remove();document.getElementById("remote-audio-"+peerId)?.remove();document.getElementById("call-participant-peer-"+peerId)?.remove()}
function syncMiniCallControls(){const muteLabel=muted?"🎙 Unmute":"🎙 Mute",shareLabel=screenStream?"▣ Stop sharing":"▣ Share screen";$("mute-button").textContent=muteLabel;$("mini-mute-button").textContent=muteLabel;$("share-button").textContent=shareLabel;$("mini-share-button").textContent=shareLabel;$("mini-call-status").textContent=muted?"On call · Muted":screenStream?"On call · Sharing screen":"On call"}
function toggleCallPanel(forceExpanded){const dock=$("call-dock");if(!voiceRoom||!dock)return;const collapsed=typeof forceExpanded==="boolean"?!forceExpanded:!dock.classList.contains("call-collapsed");dock.classList.toggle("call-collapsed",collapsed);$("call-collapse-button").textContent=collapsed?"Minimize":"Minimize";$("call-collapse-button").setAttribute("aria-expanded",String(!collapsed));$("mini-expand-button").setAttribute("aria-label","Maximize call");syncMiniCallControls()}
$("call-collapse-button").onclick=()=>toggleCallPanel(false);
$("mini-expand-button").onclick=()=>toggleCallPanel(true);

async function joinVoiceCall(type,id,invite=true){if(voiceRoom){if(voiceRoom.type===type&&String(voiceRoom.id)===String(id))return;await leaveVoiceCall()}ensureVoiceSocket();if(!socket)throw Error("Voice connection is unavailable. Refresh and try again.");if(!navigator.mediaDevices?.getUserMedia)throw Error("Microphone access requires a supported browser on HTTPS.");try{localStream=await navigator.mediaDevices.getUserMedia({audio:true,video:false});const config=await api("/api/voice-config");iceServers=config.iceServers;if(!socket.connected)await new Promise((resolve,reject)=>{socket.once("connect",resolve);socket.once("connect_error",()=>reject(Error("Could not connect to voice server.")))});const result=await new Promise((resolve,reject)=>socket.emit("voice:join",{type,id:String(id)},r=>r?.ok?resolve(r):reject(Error(r?.error||"Could not join voice."))));voiceRoom={type,id:String(id)};muted=false;$("mute-button").textContent="🎙 Mute";$("mini-mute-button").textContent="🎙 Mute";$("mini-share-button").textContent="▣ Share screen";$("call-title").textContent=type==="dm"?"Direct voice call":"General Voice";$("call-subtitle").textContent=type==="dm"?"Private voice channel":"Server voice channel";$("call-dock").classList.remove("hidden","call-collapsed");$("call-collapse-button").textContent="Minimize";$("call-collapse-button").setAttribute("aria-expanded","true");$("share-button").disabled=!navigator.mediaDevices.getDisplayMedia;$("mini-share-button").disabled=!navigator.mediaDevices.getDisplayMedia;syncMiniCallControls();addCallParticipant("local",user.displayName||user.username,user.avatarData,true);result.peers.forEach(p=>makePeer(p.peerId,true));if(type==="dm"&&invite)$("call-subtitle").textContent="Calling… waiting for your friend";}catch(e){if(localStream){localStream.getTracks().forEach(t=>t.stop());localStream=null}throw e}}
async function leaveVoiceCall(notify=true){if(screenStream){screenStream.getTracks().forEach(t=>t.stop());screenStream=null}peerConnections.forEach((pc,id)=>{pc.close();document.getElementById("remote-"+id)?.remove()});peerConnections.clear();remoteStreams.clear();if(localStream){localStream.getTracks().forEach(t=>t.stop());localStream=null}if(notify&&socket&&voiceRoom)socket.emit("voice:leave");voiceRoom=null;muted=false;$("server-voice-join").innerHTML="◖ General Voice <span>Join</span>";$("call-dock").classList.add("hidden");$("call-dock").classList.remove("call-collapsed");$("call-collapse-button").textContent="Minimize";$("call-collapse-button").setAttribute("aria-expanded","true");$("call-stage").replaceChildren();$("mute-button").textContent="🎙 Mute";$("mini-mute-button").textContent="🎙 Mute";$("share-button").textContent="▣ Share screen";$("mini-share-button").textContent="▣ Share screen";$("mini-call-status").textContent="On call"}
async function toggleScreenShare(){if(!voiceRoom)return;let captured=null;try{if(screenStream){await stopScreenShare();return}captured=await navigator.mediaDevices.getDisplayMedia({video:{width:{ideal:1280,max:1920},height:{ideal:720,max:1080},frameRate:{ideal:24,max:30}},audio:false});screenStream=captured;const track=screenStream.getVideoTracks()[0];track.contentHint="detail";const preview=document.createElement("video");preview.id="local-screen-preview";preview.srcObject=screenStream;preview.autoplay=true;preview.muted=true;preview.playsInline=true;preview.className="local-screen";$("call-stage").prepend(preview);const senders=[...peerConnections.values()].map(pc=>pc.getTransceivers().find(t=>t.receiver.track.kind==="video")?.sender).filter(Boolean);await Promise.all(senders.map(async sender=>{await sender.replaceTrack(track);try{const params=sender.getParameters();if(!params.encodings?.length)params.encodings=[{}];params.encodings[0].maxBitrate=1800000;params.encodings[0].maxFramerate=24;params.degradationPreference="maintain-resolution";await sender.setParameters(params)}catch(e){console.debug("Screen-share quality hints unavailable:",e)}}));syncMiniCallControls();track.onended=()=>stopScreenShare()}catch(e){captured?.getTracks().forEach(t=>t.stop());screenStream=null;document.getElementById("local-screen-preview")?.remove();if(e.name!=="NotAllowedError")alert("Could not share your screen: "+e.message)}}
async function stopScreenShare(){if(!screenStream)return;screenStream.getTracks().forEach(t=>t.stop());screenStream=null;document.getElementById("local-screen-preview")?.remove();syncMiniCallControls();const senders=[...peerConnections.values()].map(pc=>pc.getTransceivers().find(t=>t.receiver.track.kind==="video")?.sender).filter(Boolean);await Promise.all(senders.map(s=>s.replaceTrack(null).catch(()=>{})))}
$("dm-call-button").onclick=()=>joinVoiceCall("dm",activeDm,true).catch(e=>alert(e.message));
$("server-voice-join").onclick=()=>{if(voiceRoom?.type==="server"){leaveVoiceCall();$("server-voice-join").innerHTML="◖ General Voice <span>Join</span>";return}joinVoiceCall("server",activeServer?.id,false).then(()=>$("server-voice-join").innerHTML="◖ General Voice <span>Leave</span>").catch(e=>alert(e.message))};
function toggleMute(){if(!localStream)return;muted=!muted;localStream.getAudioTracks().forEach(t=>t.enabled=!muted);syncMiniCallControls()}
$("mute-button").onclick=toggleMute;
$("mini-mute-button").onclick=toggleMute;
$("share-button").onclick=()=>toggleScreenShare();
$("mini-share-button").onclick=()=>toggleScreenShare();
$("leave-call-button").onclick=()=>{leaveVoiceCall();$("server-voice-join").innerHTML="◖ General Voice <span>Join</span>"};
$("accept-call-button").onclick=()=>{const id=incomingDmId;incomingDmId=null;$("incoming-call-dialog").close();loadDms().then(()=>{openDm(id);joinVoiceCall("dm",id,false).catch(e=>alert(e.message))})};
$("decline-call-button").onclick=()=>{if(socket&&incomingDmId)socket.emit("voice:decline",{dmId:incomingDmId});$("incoming-call-dialog").close();incomingDmId=null};

function theme(t){document.documentElement.dataset.theme=t;localStorage.setItem("emnity-social-theme",t);$("theme-toggle").textContent=t==="dark"?"☼":"☾"}
async function heartbeat(){if(!user)return;try{await api("/api/heartbeat",{method:"POST",body:"{}"})}catch{}}
async function loadServers(){if(!user)return;try{const d=await api("/api/servers");servers=d.servers;renderServers();if(activeServer&&!servers.some(s=>String(s.id)===String(activeServer.id)))home()}catch(e){console.error(e)}}
function renderServers(){$("server-list").replaceChildren();$("server-rail-list").replaceChildren();servers.forEach(s=>{const b=document.createElement("button");b.textContent=s.name;b.className=String(s.id)===String(activeServer?.id)?"active":"";b.onclick=()=>openServer(s.id);$("server-list").append(b);const rb=document.createElement("button");rb.textContent=s.name.slice(0,1).toUpperCase();rb.title=s.name;rb.className=b.className;rb.onclick=()=>openServer(s.id);$("server-rail-list").append(rb)})}
function renderServerInvite(code){const area=$("invite-display");area.replaceChildren();const label=document.createElement("span");const link=new URL("/?invite="+encodeURIComponent(code),location.origin).href;label.textContent="Invite link: "+link;const copy=document.createElement("button");copy.type="button";copy.className="small-action";copy.textContent="Copy invite link";copy.onclick=async()=>{try{await navigator.clipboard.writeText(link);showToast("Invite link copied.","success")}catch{showToast("Could not copy the link. You can copy it from the invite text.")}};area.append(label,copy)}
async function joinServerFromLink(){const params=new URLSearchParams(location.search),invite=params.get("invite");if(!invite)return;params.delete("invite");const query=params.toString();history.replaceState({},document.title,location.pathname+(query?"?"+query:"")+location.hash);try{const d=await api("/api/servers/join",{method:"POST",body:JSON.stringify({invite})});await loadServers();await openServer(d.server.id);showToast("You joined "+d.server.name+".","success")}catch(e){showToast(e.message)}}
async function loadDms(){if(!user)return;try{const d=await api("/api/dms");dms=d.dms;renderDms()}catch(e){console.error(e)}}
function renderDms(){$("dm-list").replaceChildren();if(!dms.length){const empty=document.createElement("div");empty.className="dm-empty";empty.textContent="No conversations yet";$("dm-list").append(empty);return}dms.forEach(dm=>{const b=document.createElement("button");b.className=String(dm.id)===String(activeDm)?"active":"";const av=document.createElement("span");av.className="dm-avatar";if(dm.avatar_data)setAvatar(av,dm.avatar_data,dm.displayName||dm.username);else av.textContent=(dm.displayName||dm.username)[0].toUpperCase();const dot=document.createElement("i");dot.className="status-dot "+(dm.status==="invisible"?"offline":dm.status||"offline");av.append(dot);const copy=document.createElement("span");copy.className="dm-copy";const name=document.createElement("strong");appendName(name,dm.displayName||dm.username,dm.siteRole||dm.site_role,null);const preview=document.createElement("small");preview.textContent=dm.last_message||"Start a conversation";copy.append(name,preview);b.append(av,copy);b.onclick=()=>openDm(dm.id);$("dm-list").append(b)})}
function home(){setMobileNav(false);stopTyping();typingUsers.clear();renderTyping();if(voiceRoom?.type==="server")leaveVoiceCall();$("dm-call-button").classList.add("hidden");modViewEnabled=false;updateModViewToggle();activeMembers=[];activeServer=null;activeChannel=null;activeDm=null;renderServers();renderDms();$("channel-area").classList.add("hidden");$("server-actions").classList.remove("hidden");$("welcome-content").classList.remove("hidden");$("chat-layout").classList.add("hidden");$("chat-layout").classList.remove("dm-mode");$("main-title").textContent="Welcome";$("main-subtitle").textContent="";if(pollTimer)clearInterval(pollTimer)}
async function openServer(id){$("dm-call-button").classList.add("hidden");modViewEnabled=false;updateModViewToggle();if(voiceRoom?.type==="server"&&String(voiceRoom.id)!==String(id))leaveVoiceCall();try{const d=await api("/api/servers/"+id);activeServer=d.server;activeServer.myServerRole=d.members.find(m=>String(m.id)===String(user.id))?.serverRole||null;setMobileNav(false);activeChannel=null;activeDm=null;renderServers();renderDms();$("chat-layout").classList.remove("dm-mode");$("server-actions").classList.add("hidden");$("channel-area").classList.remove("hidden");$("welcome-content").classList.add("hidden");$("chat-layout").classList.remove("hidden");$("main-title").textContent=d.server.name;$("main-subtitle").textContent="";renderServerInvite(d.server.invite_code);$("channel-list").replaceChildren();d.channels.forEach(c=>{const b=document.createElement("button");b.textContent=c.name;b.className=String(c.id)===String(activeChannel)?"active":"";b.onclick=()=>openChannel(c);$("channel-list").append(b)});renderMembers(d.members);if(d.channels[0])openChannel(d.channels[0]);else{$("message-list").replaceChildren()}}catch(e){alert(e.message)}}
function renderMembers(list){activeMembers=list;$("member-count").textContent=list.length;updateModViewToggle();$("member-list").replaceChildren();const labels={online:"Online",idle:"Idle",dnd:"Do Not Disturb",offline:"Offline"};let previous="";list.forEach(m=>{if(m.status!==previous){previous=m.status;const h=document.createElement("div");h.className="member-heading";h.textContent=labels[m.status]||m.status;$("member-list").append(h)}const row=document.createElement("div");row.className="member "+(m.status==="offline"?"offline":"");row.dataset.username=m.username;const av=document.createElement("div");av.className="member-avatar";if(m.avatarData)setAvatar(av,m.avatarData,m.displayName||m.username);else av.textContent=(m.displayName||m.username)[0].toUpperCase();const dot=document.createElement("i");dot.className="status-dot "+(m.status==="dnd"?"dnd":m.status==="idle"?"idle":m.status==="offline"?"offline":"online");av.append(dot);const name=document.createElement("span");name.className="member-name";appendName(name,m.displayName||m.username,m.siteRole,m.serverRole);row.append(av,name);if(modViewEnabled&&String(m.id)!==String(user?.id))appendModerationActions(row,m.username,m.siteRole||m.site_role,m.serverRole||m.server_role);$("member-list").append(row)})}
function openChannel(c){window.emnityClearReply?.();selectedAttachments=[];renderAttachmentPreview();setMobileNav(false);stopTyping();activeDm=null;activeChannel=c.id;watchTyping("channel",c.id);$("chat-layout").classList.remove("dm-mode");lastMessageId=0;$("main-title").textContent=activeServer.name;$("main-subtitle").textContent=" / #"+c.name;$("message-input").placeholder="Message #"+c.name; $("message-input").title="Use @username to mention someone. Commands: /leave and /role @username Mod";$("channel-list").querySelectorAll("button").forEach(b=>b.classList.toggle("active",b.textContent===c.name));renderDms();$("message-list").replaceChildren();loadMessages(true);if(pollTimer)clearInterval(pollTimer);pollTimer=setInterval(()=>{loadMessages(false);refreshServer()},3000)}
async function openDm(id){window.emnityClearReply?.();selectedAttachments=[];renderAttachmentPreview();stopTyping();if(voiceRoom?.type==="dm"&&String(voiceRoom.id)!==String(id))leaveVoiceCall();const dm=dms.find(x=>String(x.id)===String(id));if(!dm)return;setMobileNav(false);activeServer=null;activeChannel=null;activeDm=dm.id;modViewEnabled=false;updateModViewToggle();watchTyping("dm",dm.id);lastMessageId=0;renderServers();renderDms();$("channel-area").classList.add("hidden");$("server-actions").classList.remove("hidden");$("welcome-content").classList.add("hidden");$("chat-layout").classList.remove("hidden");$("chat-layout").classList.add("dm-mode");$("dm-call-button").classList.remove("hidden");$("main-title").replaceChildren();appendName($("main-title"),dm.displayName||dm.username,dm.siteRole||dm.site_role,null);$("main-subtitle").textContent=" · @"+dm.username;$("message-input").placeholder="Message @"+dm.username; $("message-input").title="Use @username to mention someone";$("message-list").replaceChildren();loadMessages(true);if(pollTimer)clearInterval(pollTimer);pollTimer=setInterval(()=>loadMessages(false),2500)}
async function refreshServer(){if(!activeServer)return;try{const d=await api("/api/servers/"+activeServer.id);activeServer.myServerRole=d.members.find(m=>String(m.id)===String(user.id))?.serverRole||null;renderMembers(d.members)}catch{}}
function roleClass(role,kind){const slug=String(role||"").toLowerCase().replace(/[^a-z]+/g,"-").replace(/^-|-$/g,"");return "role-badge role-"+kind+"-"+slug}
function appendRoleBadge(parent,role,kind){if(!role)return;const badge=document.createElement("span");badge.className=roleClass(role,kind);badge.textContent=role;parent.append(badge)}
function appendName(parent,name,siteRole,serverRole){appendRoleBadge(parent,siteRole,"site");appendRoleBadge(parent,serverRole,"server");parent.append(document.createTextNode(name||"Unknown"))}
function renderMentionText(parent,content){const pattern=/@([a-zA-Z0-9_-]{3,20})/g;let last=0,match;while((match=pattern.exec(content))){if(match.index>last)parent.append(document.createTextNode(content.slice(last,match.index)));const mention=document.createElement("span");mention.className="chat-mention";mention.textContent=match[0];parent.append(mention);last=pattern.lastIndex}if(last<content.length)parent.append(document.createTextNode(content.slice(last)))}
function renderTyping(){const names=[...typingUsers.values()];$("typing-indicator").textContent=names.length===0?"":names.length===1?names[0]+" is typing...":names.length===2?names.join(" and ")+" are typing...":names.slice(0,2).join(", ")+", and others are typing..."}
function isCurrentTypingChat(p){return p.type===(activeDm?"dm":"channel")&&String(p.id)===String(activeDm||activeChannel)}
function watchTyping(type,id){typingUsers.clear();renderTyping();typingActive=false;if(typingTimer)clearTimeout(typingTimer);if(socket?.connected)socket.emit("typing:watch",{type,id})}
function updateTyping(){if(!socket?.connected||(!activeChannel&&!activeDm))return;const type=activeDm?"dm":"channel",id=activeDm||activeChannel;if(!typingActive){typingActive=true;socket.emit("typing:update",{type,id,isTyping:true})}if(typingTimer)clearTimeout(typingTimer);typingTimer=setTimeout(()=>stopTyping(),1400)}
function stopTyping(){if(typingTimer)clearTimeout(typingTimer);typingTimer=null;if(!typingActive)return;typingActive=false;if(socket?.connected&&(activeChannel||activeDm))socket.emit("typing:update",{type:activeDm?"dm":"channel",id:activeDm||activeChannel,isTyping:false})}
function markMessageDeleted(messageId){const row=[...$("message-list").querySelectorAll("[data-message-id]")].find(el=>el.dataset.messageId===String(messageId));if(!row)return;const body=row.querySelector(".message-body");if(body)body.textContent="This message was deleted";row.classList.add("message-deleted");row.querySelector(".message-delete")?.remove()}
function markMessageDeleted(messageId){const row=[...$("message-list").querySelectorAll("[data-message-id]")].find(el=>el.dataset.messageId===String(messageId));if(!row)return;const body=row.querySelector(".message-body");if(body)body.textContent="This message was deleted";row.classList.add("message-deleted");row.querySelector(".message-delete")?.remove()}
function renderMessage(m){const row=document.createElement("article");row.className="message";if(activeServer&&!activeDm&&/(^|\s)@everyone(?=$|\s|[.,!?])/i.test(m.content||""))row.classList.add("message-everyone");row.dataset.messageId=String(m.id);row.dataset.chatType=activeDm?"dm":"channel";row.dataset.chatId=String(activeDm||activeChannel);row.__message=m;const own=String(m.user_id)===String(user?.id);if(own)row.classList.add("message-own");const av=document.createElement("div");av.className="message-avatar";if(m.avatar_data)setAvatar(av,m.avatar_data,m.display_name||m.username);else av.textContent=(m.display_name||m.username)[0].toUpperCase();const body=document.createElement("div"),head=document.createElement("div");head.className="message-head";const name=document.createElement("strong");appendName(name,m.display_name||m.username,m.site_role||m.siteRole,m.server_role||m.serverRole);const time=document.createElement("time");time.textContent=new Date(m.created_at).toLocaleString();head.append(name);if(modViewEnabled&&!own&&activeServer)appendModerationActions(head,m.username,m.site_role||m.siteRole,m.server_role||m.serverRole);head.append(time);const text=document.createElement("div");text.className="message-body";if(m.deleted_at){text.textContent="This message was deleted";row.classList.add("message-deleted")}else renderMentionText(text,m.content);body.append(head,text);if(!m.deleted_at&&Array.isArray(m.attachments)&&m.attachments.length){const files=document.createElement("div");files.className="message-attachments";m.attachments.forEach(file=>{const url="/api/attachments/"+encodeURIComponent(file.id);if(["image/png","image/jpeg","image/gif","image/webp"].includes(file.type)){const link=document.createElement("a");link.href=url;link.target="_blank";link.rel="noopener noreferrer";link.className="message-image-link";const img=document.createElement("img");img.src=url;img.alt=file.name;img.loading="lazy";img.className="message-image";link.append(img);files.append(link)}else{const link=document.createElement("a");link.href=url;link.className="message-file-card";link.download=file.name;const glyph=document.createElement("span");glyph.className="message-file-icon";glyph.textContent="↧";const meta=document.createElement("span");meta.className="message-file-meta";const title=document.createElement("strong");title.textContent=file.name;const size=document.createElement("small");size.textContent=formatFileSize(file.size);meta.append(title,size);link.append(glyph,meta);files.append(link)}});body.append(files)}if(own&&!m.deleted_at){const del=document.createElement("button");del.type="button";del.className="message-delete";del.textContent="Delete";del.title="Delete this message for everyone";del.onclick=async()=>{if(!confirm("Delete this message for everyone?"))return;del.disabled=true;try{const endpoint=activeDm?"/api/dms/"+activeDm+"/messages/":"/api/channels/"+activeChannel+"/messages/";await api(endpoint+encodeURIComponent(m.id),{method:"DELETE"});markMessageDeleted(m.id)}catch(e){del.disabled=false;alert(e.message)}};body.append(del)}row.append(av,body);$("message-list").append(row)}
async function loadMessages(initial){if(!activeChannel&&!activeDm)return;const endpoint=activeDm?"/api/dms/"+activeDm+"/messages":"/api/channels/"+activeChannel+"/messages";try{const d=await api(endpoint+"?after="+(initial?0:lastMessageId));if(initial)$("message-list").replaceChildren();d.messages.forEach(m=>{renderMessage(m);lastMessageId=Math.max(lastMessageId,Number(m.id))});if(d.messages.length&&(initial||$("message-list").scrollHeight-$("message-list").scrollTop-$("message-list").clientHeight<100))$("message-list").scrollTop=$("message-list").scrollHeight;if(initial&&!d.messages.length){const empty=document.createElement("div");empty.className="chat-empty";empty.textContent="No messages yet. Say hello!";$("message-list").append(empty)}}catch(e){console.error(e)}}
async function createDm(){const username=await showInputDialog({title:"Start a conversation",description:"Enter your friend's Emnity username to start a direct message.",placeholder:"Username",submitLabel:"Start DM"});if(username===null)return;try{const d=await api("/api/dms",{method:"POST",body:JSON.stringify({username})});await loadDms();openDm(d.dm.id);showToast("Direct message ready.","success")}catch(e){showToast(e.message)}}
async function createServer(){const name=await showInputDialog({title:"Create a server",description:"Give your new server a name. You can invite friends after it's created.",placeholder:"My server",submitLabel:"Create server"});if(name===null)return;try{const d=await api("/api/servers",{method:"POST",body:JSON.stringify({name})});await loadServers();openServer(d.server.id);showToast("Server created.","success")}catch(e){showToast(e.message)}}
async function joinServer(){const invite=await showInputDialog({title:"Join a server",description:"Paste a server invite code or invite link.",placeholder:"Invite code or link",submitLabel:"Join server"});if(invite===null)return;try{const value=invite.includes("invite=")?new URL(invite,location.origin).searchParams.get("invite"):invite;const d=await api("/api/servers/join",{method:"POST",body:JSON.stringify({invite:value||invite})});await loadServers();openServer(d.server.id);showToast("You joined "+d.server.name+".","success")}catch(e){showToast(e.message)}}
async function renameServer(){if(!activeServer)return;const name=prompt("New server name:",activeServer.name);if(name===null)return;try{const d=await api("/api/servers/"+activeServer.id,{method:"PATCH",body:JSON.stringify({name})});activeServer=d.server;$("main-title").textContent=d.server.name;renderServerInvite(d.server.invite_code);await loadServers();}catch(e){alert(e.message)}}
async function createChannel(){if(!activeServer)return;const name=prompt("New channel name (letters, numbers, hyphens):");if(name===null)return;try{const d=await api("/api/servers/"+activeServer.id+"/channels",{method:"POST",body:JSON.stringify({name})});await openServer(activeServer.id);openChannel(d.channel)}catch(e){alert(e.message)}}
function requireTermsAgreement(){return new Promise(resolve=>{const dialog=$("terms-dialog"),agree=$("terms-agree");const finish=()=>{dialog.close();agree.removeEventListener("click",finish);resolve(true)};dialog.addEventListener("cancel",e=>e.preventDefault());agree.addEventListener("click",finish);dialog.showModal()})}
