$("auth-form").onsubmit=async e=>{e.preventDefault();$("auth-submit").disabled=true;msg($("auth-message"),"");try{const d=await api(authMode==="register"?"/api/register":"/api/login",{method:"POST",body:JSON.stringify({username:$("username").value.trim(),password:$("password").value,displayName:$("display-name").value.trim()})});if(authMode==="register")await requireTermsAgreement();$("password").value="";showApp(d.user)}catch(e){msg($("auth-message"),e.message)}finally{$("auth-submit").disabled=false}};
