$("profile-form").onsubmit=async e=>{e.preventDefault();try{const body={displayName:$("edit-display-name").value,aboutMe:$("social-about-me")?.value||""};if(window.emnityBannerData!==undefined)body.profileBanner=window.emnityBannerData;if(pendingAvatarData!==undefined)body.avatarData=pendingAvatarData;const d=await api("/api/profile",{method:"PATCH",body:JSON.stringify(body)});pendingAvatarData=undefined;window.emnityBannerData=undefined;showApp(d.user);msg($("profile-message"),"Personal settings saved.",true)}catch(e){msg($("profile-message"),e.message)}};

function canPostSiteAnnouncements(){return ["Dev","Sr. Mod"].includes(user?.siteRole)}
const pendingSiteAnnouncements=[];
function queueSiteAnnouncement(p){if(!p||typeof p.title!=="string"||typeof p.body!=="string")return;pendingSiteAnnouncements.push(p);showNextSiteAnnouncement()}
function showNextSiteAnnouncement(){const dialog=$("site-announcement-dialog");if(!dialog||dialog.open||!pendingSiteAnnouncements.length)return;const p=pendingSiteAnnouncements.shift();$("site-announcement-popup-title").textContent=p.title;$("site-announcement-popup-body").textContent=p.body;if($("profile-dialog").open)$("profile-dialog").close();dialog.showModal()}
$("site-announcement-ok").onclick=()=>{$("site-announcement-dialog").close();showNextSiteAnnouncement()};
$("site-announcement-dialog").addEventListener("cancel",e=>{e.preventDefault()});

function canSiteModerate(){return ["Mod","Jr. Mod","Sr. Mod","Dev"].includes(user?.siteRole)}
function canServerBan(){return !!activeServer&&(String(activeServer.owner_id)===String(user.id)||activeServer.myServerRole==="Sr. Mod")}
function canServerTimeout(){return !!activeServer&&(String(activeServer.owner_id)===String(user.id)||["Mod","Jr. Mod","Sr. Mod"].includes(activeServer.myServerRole))}
function normalizeModRole(role){return String(role||"").trim().toLowerCase().replace(/\s+/g," ")}
function currentSiteRole(){return user?.siteRole??user?.site_role??null}
function currentServerRole(){return activeServer?.myServerRole??activeServer?.my_server_role??null}
function canUseSiteModeration(){return ["mod","jr. mod","sr. mod","dev"].includes(normalizeModRole(currentSiteRole()))}
function canUseServerModeration(){return !!activeServer&&(String(activeServer.owner_id)===String(user?.id)||["mod","jr. mod","sr. mod"].includes(normalizeModRole(currentServerRole())))}
function updateModViewToggle(){const toggle=$("mod-view-toggle");if(!toggle)return;const allowed=!!activeServer&&!activeDm&&(canUseSiteModeration()||canUseServerModeration());toggle.classList.toggle("hidden",!allowed);toggle.textContent="Mod view: "+(modViewEnabled?"On":"Off");toggle.setAttribute("aria-pressed",String(modViewEnabled));toggle.title=modViewEnabled?"Hide moderation controls":"Show moderation controls"}
function canBanTargetSiteRole(targetRole){if(!targetRole)return true;const actor=normalizeModRole(currentSiteRole()),target=normalizeModRole(targetRole);if(target==="dev")return false;if(target==="sr. mod")return actor==="dev";return actor==="dev"||actor==="sr. mod"}
function canBanTargetServerRole(targetRole){const actor=String(currentServerRole()|| (String(activeServer?.owner_id)===String(user?.id)?"Owner":"")).trim().toLowerCase(),target=String(targetRole||"").trim().toLowerCase();if(target==="owner")return false;if(target==="sr. mod")return actor==="owner";if(target==="mod"||target==="jr. mod")return actor==="owner"||actor==="sr. mod";return actor==="owner"||actor==="sr. mod"}
function appendModerationActions(parent,username,targetSiteRole,targetServerRole){const siteScope=canUseSiteModeration(),scope=siteScope?"site":"server",serverId=activeServer?.id,siteRole=normalizeModRole(currentSiteRole()),serverRole=normalizeModRole(currentServerRole()),senior=siteScope?["sr. mod","dev"].includes(siteRole):true;const canBan=siteScope?canBanTargetSiteRole(targetSiteRole):((String(activeServer?.owner_id)===String(user?.id)||serverRole==="sr. mod")&&(targetSiteRole?canBanTargetSiteRole(targetSiteRole):canBanTargetServerRole(targetServerRole)));const canUnban=siteScope?["jr. mod","sr. mod","dev"].includes(siteRole):String(activeServer?.owner_id)===String(user?.id)||serverRole==="sr. mod";const canTimeout=siteScope||String(activeServer?.owner_id)===String(user?.id)||["mod","jr. mod","sr. mod"].includes(serverRole);const wrap=document.createElement("span");wrap.className="inline-mod-actions";if(canBan){const ban=document.createElement("button");ban.type="button";ban.className="member-mod-action";ban.textContent="Ban";ban.title="Ban @"+username;ban.onclick=()=>runModerationAction("ban",username,scope,serverId,senior);wrap.append(ban)}if(canUnban){const unban=document.createElement("button");unban.type="button";unban.className="member-mod-action";unban.textContent="Unban";unban.title="Remove ban from @"+username;unban.onclick=()=>runModerationAction("unban",username,scope,serverId,senior);wrap.append(unban)}if(canTimeout){const timeout=document.createElement("button");timeout.type="button";timeout.className="member-mod-action";timeout.textContent="10m";timeout.title="10-minute timeout for @"+username;timeout.onclick=()=>runModerationAction("timeout",username,scope,serverId);wrap.append(timeout)}parent.append(wrap)}
$("mod-view-toggle").onclick=()=>{modViewEnabled=!modViewEnabled;updateModViewToggle();renderMembers(activeMembers);if(activeChannel)loadMessages(true)};
async function runModerationAction(action,username,scope,serverId,senior=false){let body={username,scope};if(scope==="server")body.serverId=serverId;if(action==="ban"){let choice=prompt(senior?"Ban duration in days (1, 3, 7, 30, 90), or enter 0 for permanent:":"Ban duration in days (1 or 7):",senior?"7":"1");if(choice===null)return;choice=choice.trim();if(choice==="0"){if(!senior)return showToast("Your role cannot issue permanent bans.");body.permanent=true}else{body.durationDays=Number(choice);if(!Number.isInteger(body.durationDays)||body.durationDays<1||(!senior&&![1,7].includes(body.durationDays))||(senior&&body.durationDays>3650))return showToast("Enter an allowed number of days.")}body.reason=prompt("Reason (optional):","")||""}if(!confirm(action==="ban"?"Apply this "+(body.permanent?"permanent":body.durationDays+" day")+" ban to @"+username+"?":action==="unban"?"Remove the ban for @"+username+"?":"Apply a 10-minute timeout to @"+username+"?"))return;try{await api("/api/moderation/"+action,{method:"POST",body:JSON.stringify(body)});showToast(action==="ban"?"Ban applied.":action==="unban"?"Ban removed.":"10-minute timeout applied.","success");if(activeServer)await refreshServer();if(activeChannel)await loadMessages(true)}catch(e){showToast(e.message)}}

async function loadSettingsServers(){const select=$("settings-server-select"),current=select.value;try{const result=await api("/api/servers");servers=result.servers;renderServers()}catch(e){msg($("server-role-message"),e.message);return}select.replaceChildren(new Option("Choose a server",""));servers.forEach(s=>select.add(new Option(s.name,s.id)));if(current&&servers.some(s=>String(s.id)===current))select.value=current;else if(activeServer)select.value=String(activeServer.id);if(select.value)loadServerRoleSettings(select.value);else $("server-role-list").textContent="Choose a server to manage its roles."}
$("settings-server-select").onchange=()=>loadServerRoleSettings($("settings-server-select").value);
async function loadServerRoleSettings(id){if(!id){$("server-role-list").textContent="Choose a server to manage its roles.";return}try{const d=await api("/api/servers/"+id);let canManage=String(d.server.owner_id)===String(user.id);if(!canManage){try{await api("/api/site-roles");canManage=true}catch{}}const wrap=$("server-role-list");wrap.replaceChildren();const isMember=d.members.some(m=>String(m.id)===String(user.id));$("leave-server-settings").hidden=!isMember;$("leave-server-settings").textContent=String(d.server.owner_id)===String(user.id)?"Delete server":"Leave server";if(!canManage){wrap.textContent="Only this server's Owner or a site administrator can manage roles.";return}d.members.forEach(m=>{const row=document.createElement("div");row.className="settings-role-row";const who=document.createElement("div");who.className="settings-role-who";const nm=document.createElement("strong");appendName(nm,m.displayName||m.username,m.siteRole,m.serverRole);const handle=document.createElement("small");handle.textContent="@"+m.username;who.append(nm,handle);row.append(who);const sel=document.createElement("select");sel.dataset.username=m.username;sel.disabled=m.serverRole==="Owner";[["Member",""],["Mod","Mod"],["Jr. Mod","Jr. Mod"],["Sr. Mod","Sr. Mod"]].forEach(([label,value])=>sel.add(new Option(label,value)));sel.value=m.serverRole||"";row.append(sel);const save=document.createElement("button");save.type="button";save.className="small-action";save.textContent="Save";save.disabled=sel.disabled;save.onclick=async()=>{try{await api("/api/servers/"+id+"/members/"+encodeURIComponent(m.username)+"/role",{method:"PATCH",body:JSON.stringify({role:sel.value||"remove"})});msg($("server-role-message"),"Updated @"+m.username+".",true);loadServerRoleSettings(id);if(activeServer&&String(activeServer.id)===String(id))refreshServer()}catch(e){msg($("server-role-message"),e.message)}};row.append(save);wrap.append(row)})}catch(e){msg($("server-role-message"),e.message)}}
$("site-role-form").onsubmit=async e=>{e.preventDefault();try{const d=await api("/api/site-roles/"+encodeURIComponent($("site-role-username").value.trim()),{method:"PATCH",body:JSON.stringify({role:$("site-role-value").value})});msg($("site-role-message"),"Updated @"+d.username+" to "+(d.siteRole||"no site role")+".",true);if(String(d.username).toLowerCase()===String(user.username).toLowerCase())user.siteRole=d.siteRole;loadServers();loadDms()}catch(e){msg($("site-role-message"),e.message)}};
$("site-announcement-form").onsubmit=async e=>{e.preventDefault();if(!canPostSiteAnnouncements())return;const button=$("site-announcement-form").querySelector("button[type=submit]");button.disabled=true;try{const d=await api("/api/site-announcements",{method:"POST",body:JSON.stringify({title:$("site-announcement-title").value.trim(),body:$("site-announcement-body").value.trim()})});msg($("site-announcement-status"),"Announcement sent to "+d.recipients+" connected users.",true);$("site-announcement-body").value=""}catch(err){msg($("site-announcement-status"),err.message)}finally{button.disabled=false;$("attach-button").disabled=false}};
$("leave-server-settings").onclick=async()=>{const id=$("settings-server-select").value;if(!id)return;const server=servers.find(x=>String(x.id)===String(id));if(!server)return;const owner=String(server.owner_id)===String(user.id);const action=owner?"Leaving as Owner permanently deletes this server and removes every member. This cannot be undone. Continue?":"Leave "+server.name+"?";if(!confirm(action))return;try{await api("/api/servers/"+id+"/leave",{method:"POST"});if(activeServer&&String(activeServer.id)===String(id))home();await loadServers();await loadSettingsServers();msg($("server-role-message"),owner?"Server deleted.":"You left the server.",true)}catch(e){msg($("server-role-message"),e.message)}};
$("create-server").onclick=$("welcome-create").onclick=$("rail-add-server").onclick=createServer;$("join-server").onclick=joinServer;$("create-channel").onclick=createChannel;$("rename-server").onclick=renameServer;$("home-button").onclick=home;$("new-dm").onclick=$("welcome-dm").onclick=createDm;
$("status-button").onclick=()=>$("status-menu").classList.toggle("hidden");$("status-menu").querySelectorAll("button").forEach(b=>b.onclick=async()=>{try{const d=await api("/api/status",{method:"PATCH",body:JSON.stringify({status:b.dataset.status})});status=d.status;$("my-status-dot").className="status-dot "+(status==="invisible"?"offline":status);$("status-menu").classList.add("hidden");if(activeServer)refreshServer();loadDms()}catch(e){alert(e.message)}});
$("message-input").addEventListener("input",updateTyping);
$("message-form").onsubmit=async e=>{e.preventDefault();stopTyping();const content=$("message-input").value.trim();if((!content&&!selectedAttachments.length)||(!activeChannel&&!activeDm))return;const button=$("message-form").querySelector(".send-button");button.disabled=true;$("attach-button").disabled=true;try{
if(!selectedAttachments.length&&activeServer&&content==="/leave"){const owner=String(activeServer.owner_id)===String(user.id);if(!confirm(owner?"Leaving as Owner permanently deletes "+activeServer.name+" and removes everyone. Continue?":"Leave "+activeServer.name+"?"))return;await api("/api/servers/"+activeServer.id+"/leave",{method:"POST"});if(voiceRoom?.type==="server"&&String(voiceRoom.id)===String(activeServer.id))leaveVoiceCall();home();await loadServers();$("message-input").value="";return;}
const serverRoleMatch=content.match(/^\/role\s+@?([a-zA-Z0-9_-]{3,20})\s+(Sr\.\s*Mod|Jr\.\s*Mod|Mod|remove)$/i);
if(serverRoleMatch&&!selectedAttachments.length){if(!activeServer)throw Error("Use /role inside a server channel.");const raw=serverRoleMatch[2].toLowerCase().replace(/\s+/g," ");const role=raw==="sr. mod"?"Sr. Mod":raw==="jr. mod"?"Jr. Mod":raw==="remove"?"remove":"Mod";await api("/api/servers/"+activeServer.id+"/members/"+encodeURIComponent(serverRoleMatch[1])+"/role",{method:"PATCH",body:JSON.stringify({role})});await refreshServer();await loadMessages(true);$("message-input").value="";return;}
const siteRoleMatch=content.match(/^\/site-role\s+@?([a-zA-Z0-9_]{3,20})\s+(Sr\.\s*Mod|Jr\.\s*Mod|Mod|Dev|remove)$/i);
if(siteRoleMatch&&!selectedAttachments.length){const raw=siteRoleMatch[2].toLowerCase().replace(/\s+/g," ");const role=raw==="sr. mod"?"Sr. Mod":raw==="jr. mod"?"Jr. Mod":raw==="remove"?"remove":raw==="dev"?"Dev":"Mod";await api("/api/site-roles/"+encodeURIComponent(siteRoleMatch[1]),{method:"PATCH",body:JSON.stringify({role})});await loadServers();await loadDms();await loadMessages(true);$("message-input").value="";return;}
const endpoint=activeDm?"/api/dms/"+activeDm+"/messages":"/api/channels/"+activeChannel+"/messages";const encodedFiles=await Promise.all(selectedAttachments.map(async file=>({name:file.name,type:file.type||"application/octet-stream",data:await fileAsBase64(file)})));const d=await api(endpoint,{method:"POST",body:JSON.stringify({content,attachments:encodedFiles,replyToId:window.emnityReplyToId||null})});const empty=$("message-list").querySelector(".chat-empty");if(empty)empty.remove();if(window.emnityReplyContext)d.message.reply=window.emnityReplyContext;renderMessage(d.message);window.emnityClearReply?.();lastMessageId=Math.max(lastMessageId,Number(d.message.id));$("message-list").scrollTop=$("message-list").scrollHeight;$("message-input").value="";selectedAttachments=[];renderAttachmentPreview();if(activeDm)loadDms()
}catch(e){alert(e.message)}finally{button.disabled=false}};
async function boot(){theme(localStorage.getItem("emnity-social-theme")||"dark");let lastError;for(let attempt=0;attempt<3;attempt++){try{const d=await api("/api/me");if(d.user)showApp(d.user);else showAuth();return}catch(e){lastError=e;if(attempt<2)await new Promise(resolve=>setTimeout(resolve,[500,1500][attempt]));}}showAuth();msg($("auth-message"),"Could not check your saved sign-in session. Check your connection and refresh; you may still be signed in. "+(lastError?.message||""));}
boot();

